import { buildSectionQuestBoard, createQuestSeenStore, type SectionQuestBoard } from './sectionQuests';

export const EMISSIONS_QUEST_SEEN_STORAGE_KEY = 'ci_emissions_quests_seen_v1';

export type EmissionsQuestInput = {
  hasAssessment?: boolean;
  hasScopeBreakdown?: boolean;
  recommendationCount?: number;
  hasOpenedAnalytics?: boolean;
  carbonScore?: number;
};

const LEVEL_META = {
  1: { label: 'Starter', caption: 'Run your first footprint assessment.' },
  2: { label: 'Baseline', caption: 'Open analytics to see hotspots.' },
  3: { label: 'Insightful', caption: 'Pick one reduction idea to explore.' },
  4: { label: 'Footprint champ', caption: 'Ready for a report goal.' },
} as const;

export function deriveEmissionsQuests(input: EmissionsQuestInput): SectionQuestBoard {
  const recommendationCount = Number(input.recommendationCount) || 0;
  const carbonScore = Number(input.carbonScore) || 0;

  return buildSectionQuestBoard(
    [
      {
        id: 'run_assessment',
        title: 'Calculate footprint',
        description: 'Answer the short assessment to get your baseline.',
        complete: Boolean(input.hasAssessment),
        path: '/carbon-footprint?section=start-assessment',
        ctaLabel: 'Start',
        focus: 'assessment',
      },
      {
        id: 'see_scopes',
        title: 'See scope split',
        description: 'Confirm Scope 1 / 2 / 3 show up in your story.',
        complete: Boolean(input.hasScopeBreakdown),
        path: '/carbon-footprint?section=overview',
        ctaLabel: 'Open overview',
        focus: 'overview',
      },
      {
        id: 'open_analytics',
        title: 'Open analytics',
        description: 'Visit the analytics tab to spot your biggest sources.',
        complete: Boolean(input.hasOpenedAnalytics) || Boolean(input.hasAssessment),
        path: '/carbon-footprint?section=carbon-analytics',
        ctaLabel: 'Analytics',
        focus: 'analytics',
      },
      {
        id: 'review_idea',
        title: 'Review a reduction idea',
        description: 'Open recommendations and pick one practical action.',
        complete: recommendationCount > 0,
        path: '/carbon-footprint?section=recommendations',
        ctaLabel: 'Ideas',
        focus: 'recommendations',
      },
      {
        id: 'score_ready',
        title: 'Score on the board',
        description: 'Reach any carbon score so reporting can use your baseline.',
        complete: carbonScore > 0 || Boolean(input.hasAssessment),
        path: '/reporting',
        ctaLabel: 'Report goal',
        focus: 'report',
      },
    ],
    LEVEL_META
  );
}

const store = createQuestSeenStore(EMISSIONS_QUEST_SEEN_STORAGE_KEY);
export const markEmissionsQuestSeen = store.markSeen;
export const detectNewEmissionsQuestCelebrations = store.detectNewCelebrations;
